import{bQ as t,aL as o,u as l,G as a}from"./chunks/framework.C1gZXFVa.js";const b=JSON.parse('{"title":"Build Your Own Bundle","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/build.md","filePath":"en/guide/build.md"}'),i={name:"en/guide/build.md"};function n(s,e,d,r,c,u){return o(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="build-your-own-bundle" tabindex="-1">Build Your Own Bundle <a class="header-anchor" href="#build-your-own-bundle" aria-label="Permalink to &quot;Build Your Own Bundle&quot;">​</a></h1><blockquote><p>Most users <strong>do not</strong> need to build: prebuilt bundles already cover 4 OSes x 2 architectures (see the <a href="/en/guide/platforms">Platform Matrix</a>), so just <a href="/en/guide/download">download one</a>. Build your own only when:</p><ul><li>you want a different Ansible version;</li><li>you want to change the set of bundled collections.</li></ul></blockquote><h2 id="build-steps" tabindex="-1">Build steps <a class="header-anchor" href="#build-steps" aria-label="Permalink to &quot;Build steps&quot;">​</a></h2><ol><li><p>Prepare a <strong>build machine</strong> that meets all of these:</p><ul><li>It can reach the internet</li><li>Its OS family, CPU architecture and Python version are the <strong>same</strong> as the offline target</li></ul></li><li><p>Clone the primary repository and run the builder:</p></li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/make-offline-bundle.sh</span></span></code></pre></div><ol start="3"><li>The result lands in <code>dist/</code>: <code>ansible-offline-install-2.0.0-bundle.tar.gz</code> plus its <code>.sha256</code> checksum file. Copy it to the offline machine and follow steps 2 and 3 of the <a href="/en/guide/quick-start">Quick Start</a>.</li></ol><blockquote><p>🌏 The builder prints Chinese by default; <code>--lang en</code> or the <code>ANSIBLE_OFFLINE_LANG=en</code> environment variable switches it to English.</p></blockquote><h2 id="options-environment-variables" tabindex="-1">Options (environment variables) <a class="header-anchor" href="#options-environment-variables" aria-label="Permalink to &quot;Options (environment variables)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Effect</th></tr></thead><tbody><tr><td><code>WITH_COLLECTIONS=0</code></td><td>Bundle Ansible only, without collections (smaller)</td></tr><tr><td><code>PYTHON_BIN=python3.11</code></td><td>Pick which Python builds the bundle (when several are installed). Without it, the script auto-detects the first interpreter &gt;= 3.11 among python3.13 / 3.12 / 3.11</td></tr><tr><td><code>PIP_INDEX_URL=https://pypi.tuna.tsinghua.edu.cn/simple</code></td><td>Use a domestic PyPI mirror when overseas networks are unreachable (Tsinghua shown; Aliyun works too)</td></tr></tbody></table><blockquote><p>Separately: to change the Ansible version, edit the <code>ansible-core</code> pin in <code>requirements.txt</code> before building.</p></blockquote><h2 id="bundled-collections" tabindex="-1">Bundled collections <a class="header-anchor" href="#bundled-collections" aria-label="Permalink to &quot;Bundled collections&quot;">​</a></h2><ul><li>Bundles downloaded from Releases already contain <code>ansible.posix</code> and <code>community.general</code> (including their dependencies); <code>install.sh</code> installs them automatically, nothing extra to do.</li><li><code>collections-requirements.yml</code> lists them; edit it and rebuild to change the set.</li><li>To skip collections at install time: <code>INSTALL_COLLECTIONS=0 bash install.sh</code>.</li></ul><div class="warning custom-block"><p class="custom-block-title">Note: where collections come from</p><p>Collections are downloaded from Ansible Galaxy overseas and have no stable domestic mirror. If the build machine cannot reach Galaxy, this step fails - in that case use a ready-made bundle from Releases instead; the bundles already include the collections.</p></div>',13)])])}const p=t(i,[["render",n]]);export{b as __pageData,p as default};
